// Use a valid, writable path from the fuzzer. FUZZ_PARAM_FILENAME() guarantees a path to a file with random data.
// Behavior if file exists is unknown, but the API should handle it.
const char *path = FUZZ_PARAM_FILENAME();
FILE *fp = create_file(path);
// If creation/opening fails, bail out to respect API contract (non-NULL on success).
if (!fp) { FUZZ_BAIL(); }
// Caller must close the FILE*. Since we cannot return FILE* to the pool, close immediately to avoid leaks.
fclose(fp);
// No outputs; the file handle is not persisted.

// Prepare optional tmpdir and name. Both may be NULL per API.
// Favor valid paths to increase successful coverage.
const char *tmpdir = *FUZZ_PARAM(unsigned int) % 2 ? FUZZ_PARAM_FILENAME() : (const char *)0;
std::string base = FUZZ_PARAM_STR();
const char *name = (*FUZZ_PARAM(unsigned int) % 2) ? base.c_str() : (const char *)0;
// Prepare an output filename buffer of reasonable size.
size_t bufcap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 32u; // [32, 1055]
std::vector<char> out(bufcap, 0);
FILE *tf = create_temp_file(tmpdir, name, out.data(), out.size());
if (!tf) { FUZZ_BAIL(); }
// Close the temp file here; we are not persisting FILE* across stubs.
fclose(tf);
// Note: We intentionally do not delete the temp file here to avoid interfering with other concurrent filesystem ops during fuzzing.

// Provide a valid path. Using an existing file increases success probability.
const char *path = FUZZ_PARAM_FILENAME();
// Invoke delete. Return value convention is unknown; we just exercise the call.
int rv = delete_file(path);
(void)rv; // suppress unused warning

// Open a readable file using the fuzzer-provided existing filename.
const char *path = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(path, "rb");
if (!fp) { FUZZ_BAIL(); }
long sz = file_size(fp);
(void)sz;
fclose(fp);

// Use a path. It may or may not be a directory; both branches are interesting.
const char *path = FUZZ_PARAM_FILENAME();
int isdir = is_directory(path);
(void)isdir;

// Use a path and provide a non-NULL struct stat as required.
const char *path = FUZZ_PARAM_FILENAME();
struct stat stbuf;
int isf = is_file(path, &stbuf);
(void)isf;

// Use an existing random file path (exists) or a random-looking string (may not exist) to cover both branches.
const char *path = (*FUZZ_PARAM(unsigned int) % 2) ? FUZZ_PARAM_FILENAME() : FUZZ_PARAM_STR().c_str();
int ex = file_exists(path);
(void)ex;

// Use two paths. Source path points to an existing random-data file to exercise the success path; dest is another path.
const char *src = FUZZ_PARAM_FILENAME();
std::string dstCandidate = FUZZ_PARAM_STR();
// Ensure destination is not empty and reasonably sized.
if (dstCandidate.empty()) { FUZZ_BAIL(); }
int rv = rename_file(src, dstCandidate.c_str());
(void)rv;

// Source must be a readable regular file; FUZZ_PARAM_FILENAME() provides one.
const char *src = FUZZ_PARAM_FILENAME();
// Destination can be any path; use another fuzz string.
std::string dst = FUZZ_PARAM_STR();
if (dst.empty()) { FUZZ_BAIL(); }
int rv = copy_file(src, dst.c_str());
(void)rv;

// Prepare a readable stream.
const char *path = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(path, "rb");
if (!fp) { FUZZ_BAIL(); }
// Buffer size must be > 0.
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u; // [1,1024]
std::vector<char> buf(cap);
char *res = fgetstr(buf.data(), buf.size(), fp);
(void)res;
fclose(fp);

// Input path must be non-NULL.
std::string in = FUZZ_PARAM_STR();
if (in.empty()) { FUZZ_BAIL(); }
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 2u; // ensure space for NUL
std::vector<char> out(cap, 0);
char *ret = splitdir(in.c_str(), out.data(), out.size());
(void)ret;

// Input path must be non-NULL.
std::string in = FUZZ_PARAM_STR();
if (in.empty()) { FUZZ_BAIL(); }
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 2u; // ensure space for NUL
std::vector<char> out(cap, 0);
char *ret = splitname(in.c_str(), out.data(), out.size());
(void)ret;

// Prepare dst buffer and src string.
std::string src = FUZZ_PARAM_STR();
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u; // size > 0
std::vector<char> dst(cap, 0);
char *ret = strncopy(dst.data(), src.c_str(), dst.size());
(void)ret;

// dst must be NUL-terminated within the provided size; initialize with a bounded prefix.
std::string initial = FUZZ_PARAM_STR();
std::string src = FUZZ_PARAM_STR();
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u; // size > 0
std::vector<char> dst(cap, 0);
// Seed dst with a prefix of initial that fits into cap-1 and ensure NUL termination.
if (cap > 1) {
    size_t n = initial.size();
    if (n >= cap) n = cap - 1;
    if (n > 0) { memcpy(dst.data(), initial.data(), n); }
    dst[n] = '\0';
}
char *ret = strncatenate(dst.data(), src.c_str(), dst.size());
(void)ret;

// dst must be a NUL-terminated buffer; size must be its total capacity.
std::string seed = FUZZ_PARAM_STR();
std::string src = FUZZ_PARAM_STR();
std::string delim = (*FUZZ_PARAM(unsigned int) % 2) ? "," : FUZZ_PARAM_STR();
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
std::vector<char> dst(cap, 0);
// Initialize dst with a bounded prefix of seed.
if (cap > 1) {
    size_t n = seed.size();
    if (n >= cap) n = cap - 1;
    if (n > 0) { memcpy(dst.data(), seed.data(), n); }
    dst[n] = '\0';
}
char *ret = str_add_list(dst.data(), dst.size(), src.c_str(), delim.c_str());
(void)ret;

// Exercise variadic formatting with safe specifiers matching provided arguments.
int v = (int)(*FUZZ_PARAM(unsigned int) % 100000u);
std::string msg = FUZZ_PARAM_STR();
warn("warn: %.*s | v=%d", (int)msg.size(), msg.c_str(), v);

// Generate a marker value. Bias some values into the JPEG marker range (0xFFxx).
unsigned int r = *FUZZ_PARAM(unsigned int);
unsigned int marker = (*FUZZ_PARAM(unsigned int) % 2)
    ? (0xFF00u | (r & 0xFFu))  // typical JPEG marker pattern
    : r;                        // arbitrary value to hit unknown-code paths
// Call the target and consume the static string result.
const char *name = jpeg_marker_name(marker);
(void)name; // Returned pointer is static storage per API; do not free.
// No inputs/outputs to persist.

